/** Meldeliste einer Mannschaft (exakte league/club-Strings wie in SUMMER_STANDINGS). */
export function getMeldeliste(
  leagueName: string,
  club: string
): Meldeliste | undefined {
  return MELDELISTEN.find(
    (m) => m.leagueName === leagueName && m.club === club
  );
}
